package imagecompression

import (
	"context"
	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageprocessing"
)

type Format = imageprocessing.Format
type Result = imageprocessing.Result

const (
	FormatJPEG = imageprocessing.FormatJPEG
	FormatPNG  = imageprocessing.FormatPNG
	FormatWebP = imageprocessing.FormatWebP
	FormatAVIF = imageprocessing.FormatAVIF
	FormatHEIF = imageprocessing.FormatHEIF
	FormatGIF  = imageprocessing.FormatGIF
	FormatBMP  = imageprocessing.FormatBMP
	FormatTIFF = imageprocessing.FormatTIFF
)

var (
	ErrEmptyImage         = imageprocessing.ErrEmptyImage
	ErrUnsupportedFormat  = imageprocessing.ErrUnsupportedFormat
	ErrInvalidImage       = imageprocessing.ErrInvalidImage
	ErrImageTooLarge      = imageprocessing.ErrImageTooLarge
	ErrAnimationTooLarge  = imageprocessing.ErrAnimationTooLarge
	ErrUnsupportedVariant = imageprocessing.ErrUnsupportedVariant
	ErrCodecUnavailable   = imageprocessing.ErrCodecUnavailable
)

type Compressor interface {
	Compress(input []byte) (Result, error)
}

type UseCase struct {
	compressor Compressor
}

func NewUseCase(compressor Compressor) UseCase {
	return UseCase{
		compressor: compressor,
	}
}

func (u UseCase) Execute(ctx context.Context, input []byte) (Result, error) {
	if len(input) == 0 {
		return Result{}, ErrEmptyImage
	}

	if err := ctx.Err(); err != nil {
		return Result{}, err
	}

	result, err := u.compressor.Compress(input)
	if err != nil {
		return Result{}, err
	}

	if err := ctx.Err(); err != nil {
		return Result{}, err
	}

	return result, nil
}

package imageresize

import (
	"context"
	"errors"
	"math"

	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageprocessing"
)

var ErrInvalidOptions = errors.New("invalid resize options")

const MaxPixels = 32_000_000
const MaxFramePixels = 64_000_000

type Info struct {
	Width       int                    `json:"width"`
	Height      int                    `json:"height"`
	Format      imageprocessing.Format `json:"format"`
	ContentType string                 `json:"contentType"`
	FrameCount  int                    `json:"frameCount"`
}

type Options struct {
	Mode            string
	Width           int
	Height          int
	Reduction       int
	KeepAspectRatio bool
	// Axis is the last dimension edited by the user when the ratio is locked.
	Axis string
}

type Result struct {
	imageprocessing.Result
	OriginalWidth  int
	OriginalHeight int
}

// A decoded source lives only for this request. The application decides the
// target dimensions; the imaging implementation owns pixels and codecs.
type Source interface {
	Info() Info
	Resize(ctx context.Context, width, height int) (imageprocessing.Result, error)
}

type Decoder interface {
	Decode(input []byte) (Source, error)
}

type UseCase struct{ decoder Decoder }

func NewUseCase(decoder Decoder) UseCase { return UseCase{decoder: decoder} }

func (u UseCase) Inspect(ctx context.Context, input []byte) (Info, error) {
	source, err := u.decode(ctx, input)
	if err != nil {
		return Info{}, err
	}
	return source.Info(), nil
}

func (u UseCase) Execute(ctx context.Context, input []byte, options Options) (Result, error) {
	if err := options.Validate(); err != nil {
		return Result{}, err
	}
	source, err := u.decode(ctx, input)
	if err != nil {
		return Result{}, err
	}
	info := source.Info()
	w, h, err := Target(info, options)
	if err != nil {
		return Result{}, err
	}
	var output imageprocessing.Result
	if w == info.Width && h == info.Height {
		output = imageprocessing.Result{Data: input, Format: info.Format, ContentType: info.ContentType, Width: w, Height: h, FrameCount: info.FrameCount, Animated: info.FrameCount > 1}
	} else {
		output, err = source.Resize(ctx, w, h)
		if err != nil {
			return Result{}, err
		}
	}
	if err := ctx.Err(); err != nil {
		return Result{}, err
	}
	return Result{Result: output, OriginalWidth: info.Width, OriginalHeight: info.Height}, nil
}

func (u UseCase) decode(ctx context.Context, input []byte) (Source, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if len(input) == 0 {
		return nil, imageprocessing.ErrEmptyImage
	}
	source, err := u.decoder.Decode(input)
	if err != nil {
		return nil, err
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return source, nil
}

func (o Options) Validate() error {
	switch o.Mode {
	case "pixels":
		if o.Width < 1 || o.Height < 1 || o.Width > MaxPixels || o.Height > MaxPixels {
			return ErrInvalidOptions
		}
		if o.Axis != "width" && o.Axis != "height" {
			return ErrInvalidOptions
		}
	case "percentage":
		if o.Reduction != 25 && o.Reduction != 50 && o.Reduction != 75 {
			return ErrInvalidOptions
		}
	default:
		return ErrInvalidOptions
	}
	return nil
}

func Target(info Info, o Options) (int, int, error) {
	if err := o.Validate(); err != nil {
		return 0, 0, err
	}
	if info.Width < 1 || info.Height < 1 || info.FrameCount < 1 {
		return 0, 0, imageprocessing.ErrInvalidImage
	}
	w, h := o.Width, o.Height
	if o.Mode == "percentage" || o.KeepAspectRatio {
		scale := float64(100-o.Reduction) / 100
		if o.Mode == "pixels" {
			scale = float64(o.Width) / float64(info.Width)
			if o.Axis == "height" {
				scale = float64(o.Height) / float64(info.Height)
			}
		}
		// Check float bounds before converting to int, including hostile ratios.
		wf, hf := math.Round(float64(info.Width)*scale), math.Round(float64(info.Height)*scale)
		if wf > MaxPixels || hf > MaxPixels {
			return 0, 0, imageprocessing.ErrImageTooLarge
		}
		w, h = max(1, int(wf)), max(1, int(hf))
	}
	if w > MaxPixels/h {
		return 0, 0, imageprocessing.ErrImageTooLarge
	}
	if info.FrameCount > 1 && w > MaxFramePixels/h/info.FrameCount {
		return 0, 0, imageprocessing.ErrAnimationTooLarge
	}
	return w, h, nil
}

package imageresize

import (
	"context"
	"errors"
	"github.com/juniorosa/go-image-optimizer/backend/internal/application/imageprocessing"
	"testing"
)

func TestTargetDimensions(t *testing.T) {
	info := Info{Width: 899, Height: 1599, FrameCount: 1}
	tests := []struct {
		name    string
		options Options
		w, h    int
		err     error
	}{
		{"half with odd dimensions", Options{Mode: "percentage", Reduction: 50}, 450, 800, nil},
		{"quarter smaller", Options{Mode: "percentage", Reduction: 25}, 674, 1199, nil},
		{"three quarters smaller", Options{Mode: "percentage", Reduction: 75}, 225, 400, nil},
		{"width anchors ratio", Options{Mode: "pixels", Width: 450, Height: 999, Axis: "width", KeepAspectRatio: true}, 450, 800, nil},
		{"height anchors ratio", Options{Mode: "pixels", Width: 999, Height: 800, Axis: "height", KeepAspectRatio: true}, 450, 800, nil},
		{"stretch", Options{Mode: "pixels", Width: 100, Height: 100, Axis: "width"}, 100, 100, nil},
		{"enlarge", Options{Mode: "pixels", Width: 1798, Height: 3198, Axis: "width", KeepAspectRatio: true}, 1798, 3198, nil},
		{"enlarge anchored to height", Options{Mode: "pixels", Width: 1, Height: 3198, Axis: "height", KeepAspectRatio: true}, 1798, 3198, nil},
		{"enlarge width and reduce height independently", Options{Mode: "pixels", Width: 1798, Height: 200, Axis: "width"}, 1798, 200, nil},
		{"invalid mode", Options{Mode: "crop"}, 0, 0, ErrInvalidOptions},
		{"invalid percentage", Options{Mode: "percentage", Reduction: 0}, 0, 0, ErrInvalidOptions},
		{"negative dimension", Options{Mode: "pixels", Width: -1, Height: 10, Axis: "width"}, 0, 0, ErrInvalidOptions},
		{"zero dimension", Options{Mode: "pixels", Width: 1, Height: 0, Axis: "width"}, 0, 0, ErrInvalidOptions},
		{"missing axis", Options{Mode: "pixels", Width: 1, Height: 1}, 0, 0, ErrInvalidOptions},
		{"unsafe dimensions", Options{Mode: "pixels", Width: 10000, Height: 10000, Axis: "width"}, 0, 0, imageprocessing.ErrImageTooLarge},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			w, h, err := Target(info, tt.options)
			if w != tt.w || h != tt.h || !errors.Is(err, tt.err) {
				t.Fatalf("got %dx%d / %v, want %dx%d / %v", w, h, err, tt.w, tt.h, tt.err)
			}
		})
	}
	if w, h, err := Target(Info{Width: 1, Height: 1, FrameCount: 1}, Options{Mode: "percentage", Reduction: 75}); err != nil || w != 1 || h != 1 {
		t.Fatalf("minimum pixel: %d %d %v", w, h, err)
	}
	_, _, err := Target(Info{Width: 10, Height: 10, FrameCount: 100}, Options{Mode: "pixels", Width: 1000, Height: 1000, Axis: "width"})
	if !errors.Is(err, imageprocessing.ErrAnimationTooLarge) {
		t.Fatalf("expected frame pixel rejection, got %v", err)
	}
	_, _, err = Target(Info{Width: 1, Height: 32_000_000, FrameCount: 1}, Options{Mode: "pixels", Width: 32_000_000, Height: 1, Axis: "width", KeepAspectRatio: true})
	if !errors.Is(err, imageprocessing.ErrImageTooLarge) {
		t.Fatalf("hostile ratio: %v", err)
	}
}

type stubDecoder struct {
	called bool
	source Source
	err    error
}

func (s *stubDecoder) Decode([]byte) (Source, error) { s.called = true; return s.source, s.err }

type stubSource struct{ called bool }

func (*stubSource) Info() Info {
	return Info{Width: 20, Height: 10, FrameCount: 1, Format: imageprocessing.FormatPNG, ContentType: "image/png"}
}
func (s *stubSource) Resize(context.Context, int, int) (imageprocessing.Result, error) {
	s.called = true
	return imageprocessing.Result{Width: 10, Height: 5, Data: []byte("resized")}, nil
}

func TestUseCaseNoOpAndCancellation(t *testing.T) {
	src := &stubSource{}
	d := &stubDecoder{source: src}
	uc := NewUseCase(d)
	input := []byte("original")
	result, err := uc.Execute(context.Background(), input, Options{Mode: "pixels", Width: 20, Height: 10, Axis: "width"})
	if err != nil || src.called || string(result.Data) != "original" || result.OriginalWidth != 20 {
		t.Fatalf("no-op: %+v %v", result, err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	d.called = false
	_, err = uc.Inspect(ctx, input)
	if !errors.Is(err, context.Canceled) || d.called {
		t.Fatalf("canceled inspect: %v", err)
	}
	_, err = uc.Execute(ctx, input, Options{Mode: "percentage", Reduction: 50})
	if !errors.Is(err, context.Canceled) || d.called {
		t.Fatalf("canceled execute: %v", err)
	}
	_, err = uc.Inspect(context.Background(), nil)
	if !errors.Is(err, imageprocessing.ErrEmptyImage) {
		t.Fatalf("empty: %v", err)
	}
	_, err = uc.Execute(context.Background(), input, Options{Mode: "percentage", Reduction: 999})
	if !errors.Is(err, ErrInvalidOptions) || d.called {
		t.Fatalf("invalid options should precede decoding: %v", err)
	}
	d.err = imageprocessing.ErrInvalidImage
	_, err = uc.Execute(context.Background(), input, Options{Mode: "percentage", Reduction: 50})
	if !errors.Is(err, d.err) {
		t.Fatalf("decode error: %v", err)
	}
}

