				t.Fatal(err)
			}
			_, _, _, transparent := decoded.At(0, 0).RGBA()
			_, _, _, partial := decoded.At(9, 9).RGBA()
			if transparent != 0 || partial < 32000 || partial > 34000 {
				t.Fatalf("alpha lost: %d %d", transparent, partial)
			}
		})
	}
}

